int Checks=0,Failures=0;
void Check(bool Pass,const char* Name){++Checks;if(!Pass)++Failures;std::cout<<(Pass?"PASS ":"FAIL ")<<Name<<'\n';}
bool Near(double A,double B){return std::abs(A-B)<1e-9;}
int Count(const FResult& R,EEventKind K){int N=0;for(const auto& E:R.Events)if(E.Kind==K)++N;return N;}
FWorldInput World(double X=300,double Y=0){FWorldInput W;W.HasTarget=true;W.Target={X,Y};W.Sweep=[](const FSweepRequest&){return FSweepResult{};};return W;}
